import itertools
import random

def price(seq):
    max_p = 0
    current_sum = 0
    for x in seq:
        current_sum += x
        max_p = max(max_p, abs(current_sum))
    return max_p

def sam_price(X):
    m = len(X)
    min_p = float('inf')
    for p in itertools.permutations(X):
        min_p = min(min_p, price(p))
    return min_p

def solve_for_X(X):
    m = len(X)
    S = sam_price(X)
    abs_X = [abs(x) for x in X]
    min_abs = min(abs_X)
    possible_a1_indices = [i for i in range(m) if abs(X[i]) == min_abs]

    def get_all_george_sequences(current_indices):
        if len(current_indices) == m:
            yield [X[i] for i in current_indices]
            return

        current_sum = sum(X[i] for i in current_indices)
        remaining_indices = [i for i in range(m) if i not in current_indices]

        min_abs_sum = float('inf')
        next_indices = []
        for i in remaining_indices:
            val = abs(current_sum + X[i])
            if val < min_abs_sum - 1e-9:
                min_abs_sum = val
                next_indices = [i]
            elif abs(val - min_abs_sum) < 1e-9:
                next_indices.append(i)

        for i in next_indices:
            yield from get_all_george_sequences(current_indices + [i])

    possible_G = []
    for i in possible_a1_indices:
        for seq in get_all_george_sequences([i]):
            possible_G.append(price(seq))

    return S, possible_G

def run_test(m, trials=1000):
    min_ratio = float('inf')
    for _ in range(trials):
        X = [random.uniform(-10, 10) for _ in range(m)]
        S, possible_G = solve_for_X(X)
        if possible_G:
            for G in possible_G:
                if G > 1e-9:
                    min_ratio = min(min_ratio, S/G)
                else:
                    # If G is 0, S/G is large, so it doesn't affect min_ratio
                    pass
    return min_ratio

for m in range(2, 8):
    print(f"m={m}, min_ratio={run_test(m, 200)}")

